import statistics
class Real:
 def __init__(self,label,value): self.label=label;self.value=value
 def __lt__(self,other): print(self.label+'-lt');return False
 def __float__(self):print(self.label);return self.value
d=statistics.NormalDist(Real('mu',2.0),Real('sigma',3.0))
print(d.mean,d.stdev)
print(statistics.NormalDist('1.5',2.5).mean)
try:statistics.NormalDist('bad')
except ValueError:print('ValueError')
try:statistics.NormalDist(Real('unreachable',2.0),-1)
except statistics.StatisticsError:print('negative')
